import { readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

// Preserve the JSON-LD hashes generated by prebuild rather than maintaining
// another CSP that silently drifts away from the generated pages.
const headers = await readFile('dist/_headers', 'utf8');
const originalCsp = headers.match(/^\s+Content-Security-Policy:\s*(.+)$/m)?.[1];
if (!originalCsp) throw new Error('Build did not generate a Content-Security-Policy');
const csp = originalCsp
  .replace(/frame-src[^;]*/, "frame-src 'self' https:")
  .concat("; form-action 'none'");

const securityHeaders = {
  'Content-Security-Policy': csp,
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'SAMEORIGIN',
  'Referrer-Policy': 'no-referrer',
  'Permissions-Policy':
    'camera=(), microphone=(), geolocation=(), payment=(), usb=(), display-capture=(self)',
  'X-Robots-Tag': 'noindex, nofollow, noarchive',
};
const quote = (value) => {
  if (/[\r\n$]/.test(value)) throw new Error('Unsafe Nginx header value');
  return value.replaceAll('\\', '\\\\').replaceAll('"', '\\"');
};
await writeFile(
  'container-security-headers.conf',
  Object.entries(securityHeaders)
    .map(([name, value]) => `add_header ${name} "${quote(value)}" always;`)
    .join('\n') + '\n',
);

// Fail closed if a future upstream merge introduces a known tracking tag.
// Cloudflare's deployment-level beacon injection is not part of this repo.
const tracker = /(?:static\.cloudflareinsights\.com|cloudflareinsights\.com\/cdn-cgi|data-cf-beacon|api\.octocounts\.com|google-analytics\.com|googletagmanager\.com)/i;
async function inspect(directory) {
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const file = join(directory, entry.name);
    if (entry.isDirectory()) await inspect(file);
    else if (/\.(?:html|js|css)$/i.test(entry.name) && tracker.test(await readFile(file, 'utf8')))
      throw new Error(`Tracking resource found in static output: ${file}`);
  }
}
await inspect('dist');
// Nginx already enforces these headers. Do not expose host-specific directives.
await Promise.all(['_headers', '_redirects'].map((file) => rm(join('dist', file), { force: true })));
